//! 🪙️ Original physical loans keep their same caller and exact actual effects across failure and unwind.
use semio_framework_job::*;
use semio_framework_value::{ValueError,ValueRefusalKind};
#[global_allocator]
static ORIGINAL_LOAN_HEAP:semio_framework_trace::HeapWitness=semio_framework_trace::HeapWitness;
use semio_framework_value::retirement::controlled::ControlledRetirement;
fn inputs()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🔣️.json")).unwrap()}
fn expected()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🧾️expected.json")).unwrap()}
fn policy()->serde_json::Value{serde_json::from_str(include_str!("🧫️fixtures/🎟️caller.json")).unwrap()}
fn grant(value:&serde_json::Value)->RetainedCloneGrant{serde_json::from_value(value.clone()).unwrap()}
fn progress(value:&serde_json::Value)->RetainedCloneProgress{serde_json::from_value(value.clone()).unwrap()}

/// 🧮️ Native loans match independently evaluated closed five-axis inputs without allocating.
#[test]
fn original_retained_loan_matches_neutral_inputs_and_nested_ceiling(){
 let inputs=inputs();let expected=expected();let policy=policy();for(index,row)in inputs.as_array().unwrap().iter().enumerate(){let original=grant(&row["original"]);let mut received=RetainedCloneProgress::default();let mut sequence=0;let mut cx=StepContext::new(OperationId(policy["operation"].as_u64().unwrap()),Generation(policy["generation"].as_u64().unwrap()),StepBudget::new(policy["fuel"].as_u64().unwrap(),policy["deadlineUs"].as_u64().unwrap(),original),root_cancel_token(),||Some(1),&mut sequence,&mut received);let _=cx.consume_retained(progress(&row["received"]));let before=cx.retained_grant();let recipient=cx.original_recipient_identity();let requested=grant(&row["requested"]);let mut called=false;let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(requested,|same|->Result<RetainedCloneGrant,OriginalTurnFailure>{called=true;assert_eq!(same.original_recipient_identity(),recipient);assert_eq!(same.operation(),OperationId(71));assert_eq!(same.generation(),Generation(3));assert_eq!(same.deadline_us(),12345);let outer=same.retained_grant();let nested=same.with_retained_loan(original,|nested|->Result<RetainedCloneGrant,OriginalTurnFailure>{Ok(nested.retained_grant())})?;assert_eq!(nested,outer);assert_eq!(same.retained_grant(),outer);Ok(outer)}));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));if expected[index]["remaining"].is_null(){assert!(result.is_err());assert!(!called)}else{assert_eq!(result.unwrap(),grant(&expected[index]["remaining"]));assert!(called)}assert_eq!(cx.retained_grant(),before);assert_eq!(cx.fuel_remaining(),8192)}
}

/// 🧳️ A real failed physical child retains its source and posted receipt before the same original funded close.
#[test]
fn original_retained_loan_physical_failure_preserves_owned_cause_and_paid_close(){
 let policy=policy();let original=grant(&policy["grant"]);let mut receipt=Default::default();let mut sequence=0;let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(8192,12345,original),root_cancel_token(),||Some(1),&mut sequence,&mut receipt);let mut cause=Some(ValueError::new(ValueRefusalKind::InvalidValue,"Original failed physical child 源🌊"));let pointer=cause.as_ref().unwrap().message.as_ptr();let mut source=None;let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:0,maximum_capacity_bytes:17,maximum_release_bytes:0,maximum_depth:8};let before=cx.retained_progress();let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|->Result<(),OriginalTurnFailure>{let mut bytes=Vec::<u8>::new();bytes.try_reserve_exact(17).unwrap();let progress=RetainedCloneProgress{copied_items:1,retained_capacity_bytes:bytes.capacity(),..Default::default()};source=Some(bytes);same.consume_fuel(1);Err(OriginalTurnFailure::debit_original(cause.take().unwrap().with_retained_progress(progress),same))}));let failure=result.unwrap_err();assert!(failure.receipt_refusal.is_none());assert_eq!(failure.primary.message().as_ptr(),pointer);assert_eq!((heap.requested_bytes,heap.released_bytes),(17,0));assert_eq!(cx.retained_progress().retained_capacity_bytes-before.retained_capacity_bytes,17);assert_eq!(cx.retained_progress().copied_items-before.copied_items,1);assert_eq!(cx.fuel_remaining(),8191);assert_eq!(cx.retained_grant().maximum_capacity_bytes,original.maximum_capacity_bytes-17);let mut owner=ControlledRetirement::new((source.take().unwrap(),failure)).unwrap_or_else(|_|panic!("original physical failure retirement unsupported"));for turn in 0..8192{if owner.terminal_is_empty(){break}let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:64,maximum_capacity_bytes:65536,maximum_release_bytes:131072,maximum_depth:128};let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|{let demand=owner.selected_demand(64)?;close_original_retained_step(same,demand,|loan|owner.step(loan))}));let progress=result.unwrap().progress();assert_eq!((heap.requested_bytes,heap.released_bytes),(progress.retained_capacity_bytes,progress.released_bytes));assert!(turn<8191)}assert!(owner.terminal_is_empty());let(_,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||drop(owner));assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));
}

/// ↩️ Unwinding a nested callback restores both original temporary ceilings without resetting its posted effects.
#[test]
fn original_retained_loan_unwind_restores_parent_without_new_context(){
 let policy=policy();let original=grant(&policy["grant"]);let mut receipt=Default::default();let mut sequence=0;let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(8192,12345,original),root_cancel_token(),||Some(1),&mut sequence,&mut receipt);let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1,maximum_capacity_bytes:1,maximum_release_bytes:1,maximum_depth:1};let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _:Result<(),OriginalTurnFailure>=cx.with_retained_loan(loan,|same|{same.consume_retained(RetainedCloneProgress{copied_items:1,..Default::default()})?;same.with_retained_loan(loan,|_|->Result<(),OriginalTurnFailure>{panic!("original loan unwind")})});}));assert!(result.is_err());assert_eq!(cx.retained_progress().copied_items,1);assert_eq!(cx.retained_grant(),RetainedCloneGrant{maximum_items:original.maximum_items-1,..original});assert_eq!(cx.deadline_us(),12345);assert_eq!(cx.operation(),OperationId(71));
}

/// 🪢️ A safe whole-context swap cannot redirect restoration or destroy either original failed cause.
#[test]
fn original_retained_loan_swap_and_replace_preserve_both_original_causes(){
 let replacement_policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️replacement.json")).unwrap();let original=grant(&policy()["grant"]);let replacement_grant=grant(&replacement_policy["grant"]);let rows:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🪢️identity.json")).unwrap();let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1,maximum_capacity_bytes:1,maximum_release_bytes:1,maximum_depth:1};
 for row in rows.as_array().unwrap().iter().filter(|row|row["outcome"]!="unwind"){let(mut first_receipt,mut second_receipt)=(Default::default(),Default::default());let(mut first_sequence,mut second_sequence)=(0,0);let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(8192,12345,original),root_cancel_token(),||Some(1),&mut first_sequence,&mut first_receipt);let mut replacement=Some(StepContext::new(OperationId(72),Generation(4),StepBudget::new(4096,23456,replacement_grant),root_cancel_token(),||Some(2),&mut second_sequence,&mut second_receipt));let mut moved=None;let failed=row["outcome"]=="failure";let mut failure=if failed{Some(OriginalTurnFailure{primary:ValueError::new(ValueRefusalKind::InvalidValue,row["primary"].as_str().unwrap()).into(),receipt_refusal:Some(ValueError::new(ValueRefusalKind::InvariantViolated,row["receiptRefusal"].as_str().unwrap())),context_refusal:None})}else{None};let pointers=failure.as_ref().map(|failure|(failure.primary.message().as_ptr(),failure.receipt_refusal.as_ref().unwrap().message.as_ptr()));
 let(result,heap)=semio_framework_trace::observe_heap_allocations_on_this_thread(||cx.with_retained_loan(loan,|same|{if row["action"]=="swap"{std::mem::swap(same,replacement.as_mut().unwrap())}else{moved=Some(std::mem::replace(same,replacement.take().unwrap()))}if failed{Err(failure.take().unwrap())}else{Ok(())}}));let failure=result.unwrap_err();assert_eq!((heap.requested_bytes,heap.released_bytes),(0,0));assert_eq!(cx.retained_grant(),replacement_grant);assert_eq!(cx.deadline_us(),23456);assert_eq!(cx.operation(),OperationId(72));assert_eq!(moved.as_ref().or(replacement.as_ref()).unwrap().retained_grant(),loan);assert!(failure.context_refusal.is_some());if let Some(pointers)=pointers{assert_eq!((failure.primary.message().as_ptr(),failure.receipt_refusal.as_ref().unwrap().message.as_ptr()),pointers)}else{assert_eq!(failure.primary_value().unwrap().kind,ValueRefusalKind::InvariantViolated)}
 }
}

/// 🛑️ Unwind restoration never writes original credits into a safely swapped replacement.
#[test]
fn original_retained_loan_swap_unwind_never_promotes_replacement(){
 let replacement_policy:serde_json::Value=serde_json::from_str(include_str!("🧫️fixtures/🎟️replacement.json")).unwrap();let original=grant(&policy()["grant"]);let replacement_grant=grant(&replacement_policy["grant"]);let(mut first_receipt,mut second_receipt)=(Default::default(),Default::default());let(mut first_sequence,mut second_sequence)=(0,0);let mut cx=StepContext::new(OperationId(71),Generation(3),StepBudget::new(8192,12345,original),root_cancel_token(),||Some(1),&mut first_sequence,&mut first_receipt);let mut replacement=StepContext::new(OperationId(72),Generation(4),StepBudget::new(4096,23456,replacement_grant),root_cancel_token(),||Some(2),&mut second_sequence,&mut second_receipt);let loan=RetainedCloneGrant{maximum_items:1,maximum_copy_bytes:1,maximum_capacity_bytes:1,maximum_release_bytes:1,maximum_depth:1};let result=std::panic::catch_unwind(std::panic::AssertUnwindSafe(||{let _:Result<(),OriginalTurnFailure>=cx.with_retained_loan(loan,|same|{std::mem::swap(same,&mut replacement);panic!("original swapped loan unwind")});}));assert!(result.is_err());assert_eq!(cx.retained_grant(),replacement_grant);assert_eq!(replacement.retained_grant(),loan);assert_eq!(cx.deadline_us(),23456);assert_eq!(replacement.deadline_us(),12345);
}
